def divisor_sum(n):
    """Return the sum of all positive divisors of n, including n itself.

    Returns 0 for non-positive or non-integer input.
    """
    if n is None:
        return 0
    if isinstance(n, float) and n.is_integer():
        n = int(n)
    if not isinstance(n, int) or n <= 0:
        return 0

    total = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            total += i
            if i != n // i:
                total += n // i
        i += 1
    return total
